-- AssembleHeads (generated by build_heads.py): run once in Studio's command bar, after importing
-- NC_Head_Male.fbx and NC_Head_Female.fbx with the 3D Importer. Select both imported models, paste this, press Enter.
-- The pieces go to ReplicatedStorage.NC_HeadAssets.<Gender>, where NCHead (the Character Studio) finds them.
local Selection = game:GetService("Selection")
local RS = game:GetService("ReplicatedStorage")
local root = RS:FindFirstChild("NC_HeadAssets") or Instance.new("Folder")
root.Name = "NC_HeadAssets"
root.Parent = RS
local done = 0
for _, model in ipairs(Selection:Get()) do
	local gender = model.Name:match("NC_Head_(%a+)")
	if not gender then
		warn("AssembleHeads: keep NC_Head_<Gender> in the name of " .. model.Name)
		continue
	end
	local old = root:FindFirstChild(gender)
	if old then
		old:Destroy()
	end
	local folder = Instance.new("Folder")
	folder.Name = gender
	for _, part in ipairs(model:GetDescendants()) do
		if part:IsA("MeshPart") then
			part.Anchored = false
			part.CanCollide, part.CanTouch, part.CanQuery, part.Massless = false, false, false, true
			part.CastShadow = false
			part.DoubleSided = false
			-- hair, brows and stubble keep their greyscale texture as a SurfaceAppearance with soft alpha
			local sa = part:FindFirstChildOfClass("SurfaceAppearance")
			if not sa and part.TextureID ~= "" then
				sa = Instance.new("SurfaceAppearance")
				sa.ColorMap = part.TextureID
				sa.Parent = part
			end
			part.TextureID = ""
			if sa then
				sa.AlphaMode = Enum.AlphaMode.Transparency
				sa.NormalMap, sa.RoughnessMap, sa.MetalnessMap = "", "", ""
			end
			for _, ch in ipairs(part:GetChildren()) do
				if not (ch:IsA("Attachment") or ch == sa) then
					ch:Destroy()
				end
			end
			part.Parent = folder
			done += 1
		end
	end
	folder.Parent = root
	model:Destroy()
end
print("AssembleHeads: " .. done .. " hair and face pieces ready in ReplicatedStorage.NC_HeadAssets")
